  // Find the dblclick event listener on the label element
  // Match the line with the addEventListener call to determine indentation
  const dblclickRE = /^([ ]*)\.\.\.\s*querySelector\(['"]label['"]\)\.addEventListener\(['"]dblclick['"],\s*function\s*\(\)\s*\{/m;
  // More direct: locate the dblclick line and extract the body from { to }); at same indent
  const lines = inspectedSource.split('\n');
  let startLine = -1;
  let indent = '';
  for (let i = 0; i < lines.length; i++) {
    if (/querySelector\(['"]label['"]\)\.addEventListener\(['"]dblclick['"]/.test(lines[i])) {
      startLine = i;
      const m = lines[i].match(/^(\s*)/);
      indent = m[1];
      break;
