  // Collect body lines from startLine+1 until we find }); at the same indent
  const bodyLines = [];
  for (let i = startLine + 1; i < lines.length; i++) {
    if (lines[i] === indent + '});') break;
    bodyLines.push(lines[i]);
  }
  this.dblclickHandlerBody = bodyLines.join('\n');
});

